document.addEventListener("DOMContentLoaded", () => {

    const widthScreen = window.innerWidth || document.documentElement.clientWidth ||
        document.body.clientWidth;

    new Swiper('#imgSlider', {
        loop: true,
        effect: 'fade',
        speed: 1000,
        fadeEffect: {
            crossFade: true
        },
        autoplay: {
            delay: 3000,
            disableOnInteraction: false,
        },
    });
});
AOS.init({
    /*disable: 'mobile',*/
    easing: 'ease-in',
    duration: 600,
    once: true,
});
